            long type = readFrameType(in, offset);
            QuicFrameType qt = QuicFrameType.getFrameType(type);
            if (qt == QuicFrameType.UNKNOWN) throw new AuditException("FRAME_ENCODING_ERROR", offset);
            checkPlacement(type, env.level, offset);
            QuicFrame frame = QuicFrameLayer.create(type);
            try {
                frame.getParser(in).parse(frame);
            } catch (AuditException e) {
                throw e;
            } catch (RuntimeException e) {
                throw new AuditException("FRAME_ENCODING_ERROR", offset);
            }
            boolean close = applyFrame(type, frame, env, offset);
            byte[] encoded = frame.getSerializer().serialize();
            canon.write(encoded, 0, encoded.length);
            if (close) { result.close = true; result.closeOffset = offset; break; }
        }
    } catch (IOException e) {
        throw new AuditException("FRAME_ENCODING_ERROR", 0);
    }
    result.payload = canon.toByteArray();
    return result;
}
