private long readFrameType(InputStream in, int offset) throws AuditException, IOException {
    int b = in.read();
    if (b < 0) throw new AuditException("FRAME_ENCODING_ERROR", offset);
    int width = 1 << (b >>> 6);
    long value = b & 0x3f;
    for (int i = 1; i < width; i++) {
        int c = in.read();
        if (c < 0) throw new AuditException("FRAME_ENCODING_ERROR", offset);
        value = (value << 8) | c;
    }
    if (Canonical.varintWidth(value) != width) throw new AuditException("FRAME_ENCODING_ERROR", offset);
    return value;
}
